'use strict';
function assignedPerspective(index=0){const a=matchingResult()[index];if(!a.switcher)return matchRoles[a.role];const wishes=rosterPreferences()[index];return matchRoles.find((_,i)=>!wishes.includes(i))||matchRoles[0];}
myRoleName=function(){return assignedPerspective(0);};
function roleOpening(){const role=myRoleName(),p=rolePerspectives[role];return `저는 ${role}의 입장에서, ${p.goal} 다만 ${p.concern}`;}
roleCard=function(large=false){if(large&&!state.roleRevealed)return `<section class="large-role"><div class="card-back"><div class="role-lock">${icon('lock',27)}</div><p>역할과 나만의 정체</p><span>역할의 목표와 걱정하는 점을 확인해요.</span><small>찬반 팀을 나누는 활동이 아니에요.</small></div></section>`;const a=myAssignment(),role=myRoleName(),p=rolePerspectives[role];return `<section class="${large?'large-role':'role-mini'}"><div class="panel-heading"><span>나의 역할</span>${!large?`<button data-action="toggle-secret">${state.secretHidden?'보기':'숨기기'}</button>`:''}</div>${!large&&state.secretHidden?'<div class="secret-hidden"><p>역할을 숨겼어요.</p></div>':`<div class="role-content">${rolePictogram(role,large?'role-pictogram-large':'role-pictogram-mini')}<h2>${role}</h2><span class="tag subtle">${p.focus}</span><p class="role-identity">나만 아는 정체 · <strong>${a.switcher?'역할 전환자':'일반 참가자'}</strong></p>${a.switcher?'<p class="fine">선택한 두 역할과 다른 역할을 맡았어요. 이 역할의 관점으로 이야기하고 정체는 비밀로 해요.</p>':`<p class="fine">${a.rank}순위로 선택한 역할이에요. 역할 전환자가 누구인지 말 속에서 단서를 찾아보세요.</p>`}<dl class="role-goals"><dt>목표</dt><dd>${p.goal}</dd><dt>걱정하는 점</dt><dd>${p.concern}</dd></dl></div>`}</section>`;};
const rankedRoleScreen=screens.role;
screens.role=()=>rankedRoleScreen().replace('두 희망 역할 모두 미배정되면 역할 전환자가 됩니다.','역할의 목표와 걱정하는 점이 토론의 입장이 돼요. 찬반 팀은 나누지 않아요.');
screens.briefing=()=>{if(!preferencesReady()||!state.ready)return heading('먼저 희망 역할을 골라 주세요.','내 실제 생각과 가까운 두 역할을 선택해요.')+preferencesPanel();const role=myRoleName(),p=rolePerspectives[role];return heading('이 역할이라면, 무엇이 중요할까요?','찬반을 따로 선택하지 않고, 배정받은 역할의 입장에서 생각을 준비해요.')+`<div class="section-grid"><article class="teacher-panel"><p class="eyebrow">오늘의 토론 주제</p><h2>${esc(topic)}</h2><div class="perspective-heading">${rolePictogram(role)}<div><h3>${role}</h3><p>${p.focus}</p></div></div><p>${p.about}</p><dl class="role-goals"><dt>목표</dt><dd>${p.goal}</dd><dt>걱정하는 점</dt><dd>${p.concern}</dd></dl><div class="teacher-hint">${icon('chat',18)}${p.question}</div><p class="fine">AI 과제 주제의 모의 게임 역할카드를 참고한 예시입니다. 찬반은 역할의 상황과 이유를 바탕으로 드러나요.</p></article><form id="opening-form" class="panel form-card"><p class="eyebrow">나의 첫 발언</p><h2>${role}인 나는…</h2><p class="fine">이 역할이 지키고 싶은 것과 걱정하는 점을 한 가지씩 이야기해보세요.</p><label class="field-label" for="opening">역할의 입장에서 준비하기 <small>선택 · 300자</small></label><textarea id="opening" class="text-input" maxlength="300" placeholder="이 역할의 입장에서 중요한 것은…">${esc(state.opening)}</textarea><button type="button" class="starter-button" data-action="opening-starter">${icon('note',15)}역할에 맞는 첫 문장 힌트</button><button class="button wide" type="submit">입장 발표로 ${icon('arrow',16)}</button><p class="fine">다른 참가자의 선택 순위와 정체는 공개하지 않아요.</p></form></div>`;};
assignmentTable=function(){const results=matchingResult(),reveal=(!isTeacher()&&current==='result')||classroom.phase==='종료';return `<div class="assignment-scroll"><table class="assignment-table"><thead><tr><th>참가자</th><th>역할</th><th>역할의 관점</th><th>정체</th></tr></thead><tbody>${results.map((a,i)=>{const role=assignedPerspective(i);return `<tr><th>${i===0?userName():['','하린','민준','서윤','도윤','지우','수빈','현우'][i]}</th><td>${role}</td><td>${rolePerspectives[role].focus}</td><td>${reveal?(a.switcher?'역할 전환자':'일반 참가자'):'결과에서 공개'}</td></tr>`;}).join('')}</tbody></table></div>`;};
const perspectiveRender=render;
render=function(){const results=matchingResult();results.forEach((a,i)=>{if(people[i])people[i].role=assignedPerspective(i);});perspectiveRender();if(!isTeacher()&&current==='discussion'){const p=$('.voice-speaker p');if(p)p.textContent=voice.active||voice.completed?myRoleName():assignedPerspective(1)+'의 입장으로 이야기해요.';}if(isTeacher()){$$('.teacher-section-title .tag.subtle').forEach(el=>{if(el.textContent.startsWith('전환자 '))el.textContent='희망 순위 비공개';});}if(!isTeacher()&&current==='result'){const h=$('#screen h1');if(h)h.textContent='서로 다른 역할, 서로 다른 이유.';const p=$('#screen .scene-heading p');if(p)p.textContent='역할의 관점과 실제 정체를 확인하며 서로의 이야기를 돌아봐요.';const note=$('.teacher-panel>.fine');if(note)note.textContent='선택 순위는 공개하지 않아요. 다른 참가자의 역할은 시연용 예시입니다.';}};
downloadReflection=function(){const text=$('#reflection-text')?.value.trim()||state.reflection.trim();if(!text){toast('먼저 돌아본 생각을 적어주세요.');return;}const role=myRoleName();const content=`whose side? · by Bridge\n주제: ${topic}\n역할: ${role}\n역할의 관점: ${rolePerspectives[role].focus}\n\n${text}\n`;const url=URL.createObjectURL(new Blob(['\ufeff'+content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='whose-side-나의-회고.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
render();
